begin;
create extension if not exists pgtap with schema extensions;
select plan(23);
insert into public.companies(id,slug,name) values ('10000000-0000-0000-0000-000000000099','isolated-test','Test');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select is((select count(*)::int from public.member_audit where company_id='10000000-0000-0000-0000-000000000001' and actor_name='عمر' and person_name='مراجع' and action='UPDATE'),1,'seed contains a named audit example');
select lives_ok($$update public.members set grant_publishing=true where company_id='10000000-0000-0000-0000-000000000001' and person_id='20000000-0000-0000-0000-000000000004'$$,'manager can edit');
select throws_ok($$update public.members set role='owner' where company_id='10000000-0000-0000-0000-000000000001' and person_id='20000000-0000-0000-0000-000000000004'$$,'P0001','only an owner can assign owner','manager cannot promote owner');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$update public.members set role='owner' where company_id='10000000-0000-0000-0000-000000000001' and person_id='20000000-0000-0000-0000-000000000004'$$,'owner can promote');
select lives_ok($$update public.members set role='viewer' where company_id='10000000-0000-0000-0000-000000000001' and person_id='20000000-0000-0000-0000-000000000004'$$,'owner can demote another owner');
select throws_ok($$select public.remove_member('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001')$$,'P0001','last owner cannot be removed or demoted','last owner protected');
select is((select count(*)::int from public.member_audit where company_id='10000000-0000-0000-0000-000000000001' and actor_id is not null),4,'seed example and changes audited with actor');
select lives_ok($$insert into public.members(company_id,person_id,role) values ('10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000004','viewer')$$,'owner can add member');
select lives_ok($$select public.remove_member('10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000004')$$,'owner can remove member');
select is((select count(*)::int from public.member_audit where company_id='10000000-0000-0000-0000-000000000002' and actor_id=auth.uid() and action in ('INSERT','DELETE')),2,'inserts and deletes audited');
select is((select count(*)::int from public.members where company_id='10000000-0000-0000-0000-000000000002' and person_id='20000000-0000-0000-0000-000000000004'),0,'removed member is absent from the list and count');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',true);
select is(public.is_member('10000000-0000-0000-0000-000000000002'),false,'removed member loses company access');
select throws_ok($$select public.remove_member('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000003')$$,'P0001','not permitted to remove members','viewer cannot remove using the member action');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$insert into public.member_invitations(company_id,email,role) values ('10000000-0000-0000-0000-000000000002','viewer@example.com','reviewer')$$,'owner can reinvite a removed member');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',true);
select lives_ok($$select public.claim_invitations()$$,'removed member can claim a new invitation');
select is(public.is_member('10000000-0000-0000-0000-000000000002'),true,'reinvitation restores company access');
select is((select role::text from public.members where company_id='10000000-0000-0000-0000-000000000002' and person_id=auth.uid()),'reviewer','reinvitation applies the newly assigned role');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',true);
with changed as (update public.members set grant_money_figures=true where company_id='10000000-0000-0000-0000-000000000001' returning 1) select is((select count(*)::int from changed),0,'reviewer cannot edit');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',true);
with changed as (update public.members set removed_at=now() where company_id='10000000-0000-0000-0000-000000000001' returning 1) select is((select count(*)::int from changed),0,'viewer cannot remove');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000005',true);
with changed as (update public.members set grant_money_figures=true where company_id='10000000-0000-0000-0000-000000000003' returning 1) select is((select count(*)::int from changed),0,'contributor cannot edit');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000001","aal":"aal1"}',true);
select is((select count(*)::int from public.companies where slug='isolated-test'),0,'agency cannot see nonmember company at aal1');
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000001","aal":"aal2"}',true);
select is(public.agency_access(),true,'agency access allowed at aal2');
select is((select count(*)::int from public.companies where slug='isolated-test'),1,'agency can see nonmember company at aal2');
select * from finish();
rollback;
